from types import SimpleNamespace

import dspy


class FakeResp(dict):
    cache_hit = False

    def __init__(self, text):
        choice = SimpleNamespace(message=SimpleNamespace(content=text, tool_calls=None), finish_reason="stop")
        super().__init__({"choices": [choice]})
        self.choices = [choice]
        self.usage = {"prompt_tokens": 1, "completion_tokens": 1, "total_tokens": 2}
        self.model = "custom/offline"


class CaptureLM(dspy.BaseLM):
    def __init__(self):
        super().__init__("custom/offline", "chat", 0.0, 1000, False)
        self.calls = []

    @property
    def supported_params(self):
        return {"response_format"}

    @property
    def supports_response_schema(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        self.calls.append({"prompt": prompt, "messages": messages, **kwargs})
        return FakeResp('{"answer": "sunny", "tool_calls": {"tool_calls": []}}')

    async def aforward(self, prompt=None, messages=None, **kwargs):
        return self.forward(prompt=prompt, messages=messages, **kwargs)


class ToolSignature(dspy.Signature):
    question: str = dspy.InputField()
    tools: list[dspy.Tool] = dspy.InputField()
    answer: str = dspy.OutputField()
    tool_calls: dspy.ToolCalls = dspy.OutputField()


def get_weather(city: str) -> str:
    return f"Weather for {city}"


lm = CaptureLM()
program = dspy.Predict(ToolSignature)
adapter = dspy.JSONAdapter(use_native_function_calling=False)

with dspy.context(lm=lm, adapter=adapter):
    pred = program(question="What is the weather in Paris?", tools=[dspy.Tool(get_weather)])

assert pred.answer == "sunny"
assert pred.tool_calls.tool_calls == []
assert lm.calls[0]["response_format"] == {"type": "json_object"}

print({"response_format": lm.calls[0]["response_format"], "answer": pred.answer, "tool_calls": pred.tool_calls.model_dump()})
